import{_ as c,h as o,i as e,c as i,v as r,p,x as l,m as n,e as A,S as s}from"./chunks/framework.Dvtg8yj2.js";const _=JSON.parse('{"title":"Warp / CTA / 占用率","description":"","frontmatter":{"title":"Warp / CTA / 占用率","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/cuda-occupancy.md","filePath":"llm/cuda-occupancy.md","lastUpdated":1788454257000}'),d={name:"llm/cuda-occupancy.md"};function h(E,a,m,C,T,u){const t=o("Mermaid");return e(),i("div",null,[a[1]||(a[1]=r('<h1 id="warp-cta-占用率" tabindex="-1">Warp / CTA / 占用率 <a class="header-anchor" href="#warp-cta-占用率" aria-label="Permalink to &quot;Warp / CTA / 占用率&quot;">​</a></h1><div class="epigraph"><p>占用率是 SM 上同时常驻的 warp 数量相对硬件上限的比例；它衡量延迟隐藏的余量，并不自动等于更高吞吐。</p><footer>—— NVIDIA CUDA C++ Programming Guide：Occupancy、Launch Configuration 与 Occupancy Calculator 相关章节</footer></div><p>GPU 把线程分层：warp 是 32 路 SIMT 的调度单位，CTA（Cooperative Thread Array，即 thread block）是能用共享内存与 <code>__syncthreads</code> 的协作组，grid 是一次 kernel 启动的全部 CTA。占用率（occupancy）描述每个 SM 上能同时驻留多少 warp（或 CTA），从而在一次长延迟（共享内存 bank 冲突、全局内存访问、指令依赖）时切到别的 warp 继续发指令。LLM 的 GEMM、<a href="/llm/flashattention">FlashAttention</a>、归一化核都在这条规则下选 block 尺寸与每线程资源。本篇写三级层次、占用率公式与限制因素、以及为什么盲目拉满占用率会伤 <a href="/llm/tensor-core">Tensor Core</a> 核。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一次 kernel 的墙钟大致取决于：每个 SM 能发出多少有用指令、访存是否被覆盖、以及有没有因为资源不够而启动不足。开发者能直接调的是：每 CTA 多少线程、每个线程多少寄存器、每 CTA 多少共享内存、以及 grid 有多大。这些量互相打架：线程越多、共享内存越大，每个 SM 能装下的 CTA 越少。装太少，延迟藏不住，流水线停；装太多但每个 CTA 太瘦，又喂不饱 Tensor Core 的 MMA tile，算术强度掉到<a href="/llm/hbm-roofline">带宽墙</a>以下。</p><p>占用率把「装得下多少 warp」收成一个 0–1 的数，便于对照硬件上限。问题不是「要不要高占用率」，而是「在寄存器、共享内存、warp 上限三条约束里，当前核的延迟隐藏够不够」。CUDA 指南与占用率计算器给的是理论上限，NCU 测到的是实现占用率；两者经常不一致。</p><h3 id="warp-与-cta-不是同一粒度" tabindex="-1">Warp 与 CTA 不是同一粒度 <a class="header-anchor" href="#warp-与-cta-不是同一粒度" aria-label="Permalink to &quot;Warp 与 CTA 不是同一粒度&quot;">​</a></h3><p>Warp 内 32 线程锁步：分歧（divergence）时两条路径串行。CTA 内多个 warp 可独立调度，但同步指令会让先到的 warp 空等。占用率按 warp 计，却常被 CTA 尺寸决定：一个 256 线程的 CTA 是 8 个 warp；SM 若最多驻留 16 个 CTA，同时最多 128 个 warp，还要再被寄存器与共享内存裁剪。说「block 设成 128 以提高占用率」而不算每线程寄存器，是在忽略真正的瓶颈。</p><p><span class="marginnote">CTA 是 CUDA 编程模型的名字；文档里也写 thread block。二者同一对象。Occupancy 有时按活跃 warp 算，有时按活跃 CTA 算，对比数字前先看分母是哪一个上限。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>理论占用率</p> \\[\\mathrm{occ} = \\frac{W_{\\mathrm{active}}}{W_{\\mathrm{max}}} \\]<p>其中 \\(W_{\\mathrm{max}}\\) 是该架构每个 SM 的最大常驻 warp 数（以对应计算能力的表格为准，不要跨代抄）。\\(W_{\\mathrm{active}}\\) 取下列约束的最小值所允许的 warp 数：</p><ul><li>每 SM 最大线程 / warp 大小；</li><li>每 SM 最大 CTA 数 × 每 CTA 的 warp 数；</li><li>寄存器文件：每线程寄存器 × 每 CTA 线程 × 驻留 CTA 数 ≤ 寄存器容量；</li><li>共享内存：每 CTA 动态+静态共享内存 × 驻留 CTA 数 ≤ SM 共享内存容量；</li><li>其它硬上限（如每 SM 的 barrier 分配）。</li></ul><p>CUDA Occupancy Calculator 与 <code>cudaOccupancyMaxActiveBlocksPerMultiprocessor</code> 做的就是这道整数规划的查表版。启动配置的目标，是在满足算法所需的 tile（例如 MMA 的 \\(m\\times n\\times k\\)、FlashAttention 的 Br/Bc）前提下，让 \\(\\mathrm{occ}\\) 处于「延迟可隐藏」的区间，而不是最大化 \\(\\mathrm{occ}\\) 本身。</p><h3 id="与-llm-核的典型取舍" tabindex="-1">与 LLM 核的典型取舍 <a class="header-anchor" href="#与-llm-核的典型取舍" aria-label="Permalink to &quot;与 LLM 核的典型取舍&quot;">​</a></h3><p>大 GEMM 走库（cuBLAS / CUTLASS）：tile 大、每线程寄存器多、占用率中等，靠 MMA 吞吐而不是靠海量 warp 藏延迟。FlashAttention 一类手写核：共享内存装 QKV 分块，占用率常被共享内存卡住；此时减小 Br/Bc 能提高占用率，却增加全局内存往返，可能更慢。Decode 阶段序列长为 1，CTA 往往很瘦，占用率低是画像本身，优化应转向<a href="/llm/decode-memory-wall">访存</a>与<a href="/llm/cuda-graph">CUDA Graph</a> 减启动，而不是把 block 无脑加大。Prefill 相反，容易有足够的 CTA 填满 SM，见<a href="/llm/prefill-compute">预填充计算</a>。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>延迟隐藏的直觉：一条访存指令的完成需要几百个周期，若 SM 上还有其它就绪 warp，调度器切过去发无关指令，墙钟不被这次访存钉死。占用率高 → 就绪 warp 的期望多 → 覆盖长延迟的概率高。但它不增加单 warp 的 ILP：若每个线程内部依赖链很长、又几乎不访存，提高占用率没有指令可发，吞吐被计算流水线宽度限制。反过来，占用率低但每个 CTA 用满 Tensor Core、共享内存命中率高，仍然可以接近峰值。</p><p>寄存器溢出（spill）是占用率陷阱。为了让编译器少用寄存器、抬高占用率，可能换来大量局部内存流量，把核从算力墙推到带宽墙。指南明确：不要为占用率数字牺牲溢出。应看 NCU 的 achieved occupancy、warp stall 原因（内存、barrier、短分数依赖），再决定减共享内存、改 CTA 形状、或接受中等占用率。</p><p><span class="marginnote">Achieved occupancy 低于 theoretical，常见原因是 grid 太小（尾波）、块内分歧、或 <code>__syncthreads</code> 让大量 warp 同时卡住。只看理论占用率会误判已经「资源允许满载」的核。</span></p><h3 id="启动配置的一条工作流" tabindex="-1">启动配置的一条工作流 <a class="header-anchor" href="#启动配置的一条工作流" aria-label="Permalink to &quot;启动配置的一条工作流&quot;">​</a></h3><p>先按算法定最小 CTA：必须放下一个 tile，线程数对齐 warp。再查每线程寄存器（编译报告或 <code>--ptxas-options=-v</code>）与共享内存，算理论驻留 CTA 数。若驻留 warp 低于「经验上能藏 L2 miss」的水平，尝试：减共享内存（更小 tile 或改阶段）、用启动边界 <code>__launch_bounds__</code> 限制寄存器、或拆核。若占用率已经高但吞吐低，转向访存合并、bank 冲突、MMA 形状与<a href="/llm/nvidia-gpu-gen">代际 Tensor Core</a>，而不是继续加线程。最后用 NCU 对真实 LLM 形状（batch、seq、head）测，不要只用正方形微基准。</p>',23)),(e(),p(s,null,{default:l(()=>[A(t,{id:"mermaid-89",class:"mermaid",graph:"flowchart%20TD%0A%20%20TILE%5B%22%E7%AE%97%E6%B3%95%20tile%20%E4%B8%8E%E5%90%8C%E6%AD%A5%E9%9C%80%E6%B1%82%22%5D%20--%3E%20CTA%5B%22%E9%80%89%E5%AE%9A%20CTA%20%E5%BD%A2%E7%8A%B6%22%5D%0A%20%20CTA%20--%3E%20REG%5B%22%E6%AF%8F%E7%BA%BF%E7%A8%8B%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%0A%20%20CTA%20--%3E%20SMEM%5B%22%E6%AF%8F%20CTA%20%E5%85%B1%E4%BA%AB%E5%86%85%E5%AD%98%22%5D%0A%20%20REG%20--%3E%20LIM%5B%22%E5%8F%96%E8%B5%84%E6%BA%90%E7%BA%A6%E6%9D%9F%E6%9C%80%E5%B0%8F%22%5D%0A%20%20SMEM%20--%3E%20LIM%0A%20%20HW%5B%22SM%20%E7%9A%84%20warp%20%E4%B8%8E%20CTA%20%E4%B8%8A%E9%99%90%22%5D%20--%3E%20LIM%0A%20%20LIM%20--%3E%20OCC%5B%22%E7%90%86%E8%AE%BA%E5%8D%A0%E7%94%A8%E7%8E%87%22%5D%0A%20%20OCC%20--%3E%20PROF%5B%22NCU%3A%20%E5%AE%9E%E7%8E%B0%E5%8D%A0%E7%94%A8%E4%B8%8E%20stall%22%5D%0A%20%20PROF%20--%3E%20TUNE%5B%22%E8%B0%83%20tile%20%2F%20%E6%8E%A5%E5%8F%97%E4%B8%AD%E7%AD%89%E5%8D%A0%E7%94%A8%20%2F%20%E6%B2%BB%E8%AE%BF%E5%AD%98%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>占用率跨架构不可比：Ampere 与 Hopper 的 \\(W_{\\mathrm{max}}\\)、寄存器文件、共享内存分区不同，同一 kernel 的 occ 数字会跳，见<a href="/llm/nvidia-gpu-gen">GPU 代际</a>。Hopper 的 warpgroup MMA 还引入「多个 warp 必须协同」的约束，单纯拉高无关 warp 的占用率可能帮不上 TMA/WGMMA 流水线。动态共享内存在运行时才定，理论占用率要按最坏请求算，否则高峰形状会突然掉驻留。</p><p>多核并存（一个 SM 上残留其它流的 CTA）使「独占占用率」在服务里不成立；推理服务的真实瓶颈经常是跨请求的调度，而不是单一 Attention kernel 的 occ。此时更应看 SM 吞吐利用率与 HBM 带宽，而不是把每个核都调到 100% 理论占用。本篇数字以 CUDA 指南与对应 compute capability 表格为准，不编造未公开的调度器宽度。</p><p><span class="marginnote">把 occupancy 写进 SLA 没有意义。它是调核过程量。用户能感知的是 TTFT、TPOT 与功耗；占用率只在解释「为什么这个 launch 配置更快」时出现。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Warp 是 32 线程调度单位，CTA/thread block 是共享内存与同步的协作组，占用率是 SM 上常驻 warp 相对上限的比。</li><li>占用率由线程、寄存器、共享内存与硬件上限共同裁剪，计算器给出理论值。</li><li>高占用率帮助隐藏长延迟，但不等于高吞吐；Tensor Core tile 与避免寄存器溢出往往更优先。</li><li>LLM 里 GEMM、FlashAttention、decode 瘦核的合理占用率区间不同，不要用一个目标百分比套所有核。</li><li>以 NCU 的实现占用与 stall 原因为准，理论 occ 只是上界。</li><li>启动配置先满足 tile，再在资源约束内找延迟可隐藏的点。</li><li>出处：NVIDIA <em>CUDA C++ Programming Guide</em> 中 Occupancy 与 Occupancy Calculator；架构上限见对应 compute capability 附录。</li></ul>',6))])}const B=c(d,[["render",h]]);export{_ as __pageData,B as default};
